### Python Part

```python
import hashlib

def calculate_md5(file_path):
    hash_object = hashlib.md5()
    with open(file_path, 'rb') as file:
        chunk = file.read(4096)
        while chunk:
            hash_object.update(chunk)
            chunk = file.read(4096)
    return hash_object.hexdigest()

class CrossLanguageHandler:

    @staticmethod
    def process_file(file_path):
        md5_result = calculate_md5(file_path)
        print(f""MD5 Hash: {md5_result}"")

        # Java integration
        mo_st_state = load_mo_st_state_from_file(file_path)
        if mo_st_state is not None:
            print(f""Loaded MoST State: {mo_st_state}"")

# Python-Java interop function
def load_mo_st_state_from_file(file_path):
    import jpype
    from jpype.types import JString

    # Start the JVM with the classpath including FileLoader.class
    if not jpype.isJVMStarted():
        jpype.startJVM(classpath=['/path/to/java/classes/or/jar'])

    try:
        FileLoader = jpype.JClass('FileLoader')
        return FileLoader.loadMoSTStateFromFile(JString(file_path))
    except Exception as e:
        print(f""Error loading MoST State: {e}"")
        return None
```

