# Python: decompress_and_print.py

import gzip
import sys

def decompress_file(gzip_file_path):
    try:
        with gzip.open(gzip_file_path, 'rb') as f_in, open(gzip_file_path[:-3], 'wb') as f_out:
            while chunk := f_in.read(1024):
                f_out.write(chunk)
    except FileNotFoundError:
        print(f""Error: The file {gzip_file_path} does not exist."")
    except IOError as e:
        print(f""I/O error occurred: {e}"")

def main():
    if len(sys.argv) != 2:
        print(""Usage: python decompress_and_print.py <compressedFile.gz>"")
        return

    gzip_file_path = sys.argv[1]

    decompress_file(gzip_file_path)

    original_file_path = gzip_file_path[:-3]  # Remove .gz extension
    try:
        with open(original_file_path, 'r') as f:
            print(f.read())
    except FileNotFoundError:
        print(f""Error: The file {original_file_path} does not exist."")
    except IOError as e:
        print(f""I/O error occurred: {e}"")

if __name__ == ""__main__"":
    main()
