    # Create the specified type of plot
    if visualization_type == 'bar':
        # Example: Plotting first two columns as bar chart
        if len(df.columns) >= 2:
            df.plot(kind='bar', x=df.columns[0], y=df.columns[1])
        else:
            raise ValueError(""CSV file must have at least two columns for a bar chart."")
    elif visualization_type == 'line':
        # Example: Plotting first column as line graph
        if len(df.columns) >= 1:
            df.plot(kind='line', x=df.columns[0], y=df.columns[1:])
        else:
            raise ValueError(""CSV file must have at least one column for a line graph."")
    else:
        raise ValueError(""Unsupported visualization type. Use 'bar' or 'line'."")

    # Save the plot as an image
    plt.savefig(output_image_path)

if __name__ == ""__main__"":
    if len(sys.argv) != 4:
        print(""Usage: python script.py <input_csv_path> <output_image_path> <visualization_type>"")
        sys.exit(1)

    input_csv_path = sys.argv[1]
    output_image_path = sys.argv[2]
    visualization_type = sys.argv[3]

    generate_visualization(input_csv_path, output_image_path, visualization_type)
