import os
import pickle

class AppState:
    def __init__(self):
        self.sequence_number = 0

def load_and_sort_state(filename):
    try:
        if os.path.exists(filename):
            with open(filename, 'rb') as file:
                current_state = pickle.load(file)
                current_state.sequence_number += 1
        else:
            print(""File not found. Creating new state object."")
            current_state = AppState()

        def extract_sequence_from_last_line(file_path):
            try:
                if os.path.exists(file_path):
                    with open(file_path, 'r') as f:
                        lines = f.readlines()
                        if lines:
                            last_line = lines[-1]
                            seq_num_str = last_line.split("": "")[1].strip()
                            return int(seq_num_str)
            except Exception as e:
                print(f""Error occurred while extracting sequence: {e}"")
            return None

        existing_seq_num = extract_sequence_from_last_line(filename + "".txt"")

        if existing_seq_num is not None:
            current_state.sequence_number += existing_seq_num

        with open(filename, 'wb') as file:
            pickle.dump(current_state, file)

    except Exception as e:
        print(f""An error occurred while loading or saving state: {e}"")

    return current_state.sequence_number

# Example usage
app_instance = AppState()
resulting_sequence_number = load_and_sort_state(""app_data.pickle"")
