import os
import shutil
import zipfile

def is_compressed(file_path):
    return zipfile.is_zipfile(file_path)

def compress_file(file_path, compression_folder='compressed_files'):
    if not is_compressed(file_path):
        with zipfile.ZipFile(f""{file_path}.zip"", 'w', zipfile.ZIP_DEFLATED) as zipf:
            zipf.write(file_path, os.path.basename(file_path))
        compressed_file = f""{file_path}.zip""
    else:
        compressed_file = file_path

    if not os.path.exists(compression_folder):
        os.makedirs(compression_folder)

    shutil.move(compressed_file, os.path.join(compression_folder, os.path.basename(compressed_file)))

# Example usage
compress_file('example_document.txt')
