    def wrapper():
        try:
            func(*args, **kwargs)
            result[""success""] = True
        except Exception as e:
            print(f""Function execution failed with exception: {e}"")

    thread = threading.Thread(target=wrapper)
    thread.start()
    thread.join()  # Wait for the thread to complete

    return result[""success""]

# Example usage:

def example_function(x, y):
    if x + y < 0:
        raise ValueError(""Sum is negative"")
    print(f""Function executed with {x} and {y}"")

# Call the function asynchronously
success = run_async(example_function, 1, -2)
print(success)  # Output: False

success = run_async(example_function, 3, 4)
print(success)  # Output: True
