import json
import random

class JSONMacReceiver:
    _factories = {}

    def __init__(self, flow_id=None, source_addr=None, dest_addr=None, traffic_class=None):
        self.flow_id = flow_id
        self.source_addr = source_addr
        self.dest_addr = dest_addr
        self.traffic_class = traffic_class

    @classmethod
    def register_factory(cls, entity_type, factory_func):
        cls._factories[entity_type] = factory_func

    @classmethod
    def create_from_json(cls, json_str):
        data = json.loads(json_str)
        entity_id = data['id']
        factory_func = cls._factories.get(entity_id)

        if not factory_func:
            raise ValueError(f""No registered factory for ID: {entity_id}"")

        return factory_func(**data)

    def to_json(self):
        data = {
            'id': self.__class__.__name__,
            'flow_id': self.flow_id,
            'source_addr': self.source_addr,
            'dest_addr': self.dest_addr,
            'traffic_class': self.traffic_class
        }
        return json.dumps(data)

    @classmethod
    def random_flow_id(cls, min_val=0, max_val=100):
        return random.randint(min_val, max_val)

    @classmethod
    def random_address(cls, length=6):
        return [random.randint(0, 255) for _ in range(length)]

    @classmethod
    def random_traffic_class(cls, min_val=0, max_val=7):
        return random.randint(min_val, max_val)

class MAC_RECEIVE_QoSData_t(JSONMacReceiver):

    @classmethod
    def create_random_instance(cls):
        flow_id = cls.random_flow_id()
        source_addr = cls.random_address()
        dest_addr = cls.random_address()
        traffic_class = cls.random_traffic_class()

        return cls(flow_id, source_addr, dest_addr, traffic_class)

# Register the factory function for MAC_RECEIVE_QoSData_t
JSONMacReceiver.register_factory('MAC_RECEIVE_QoSData_t', MAC_RECEIVE_QoSData_t.create_random_instance)

def generate_mac_qos_entities(count):
    entities = []
    for _ in range(count):
        entity = MAC_RECEIVE_QoSData_t.create_random_instance()
        entities.append(entity.to_json())

    return entities

# Example usage
if __name__ == ""__main__"":
    entities_list = generate_mac_qos_entities(5)
    for entity_json in entities_list:
        print(entity_json)
```

