def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            abort(401, description=""Token is missing"")

        try:
            data = jwt.decode(token.split()[1], JWT_SECRET_KEY, algorithms=['HS256'])
            request.user_id = data['user_id']
        except Exception as e:
            abort(403, description=str(e))

        return f(*args, **kwargs)
    return decorated

# Routes
@app.route('/upload', methods=['POST'])
@token_required
def upload_file():
    if 'file' not in request.files:
        abort(400, description=""No file part"")

    file = request.files['file']
    if file.filename == '':
        abort(400, description=""No selected file"")

    if file and allowed_file(file.filename):
        filename_hashed = hash_filename(file.filename)
        unique_id = str(uuid.uuid4())
        encrypted_data = cipher_suite.encrypt(file.read())

        filepath = os.path.join(app.config['UPLOAD_FOLDER'], f""{unique_id}_{filename_hashed}"")
        with open(filepath, 'wb') as f:
            f.write(encrypted_data)

        return jsonify({'file_id': unique_id}), 201

    abort(400, description=""File type not allowed"")

@app.route('/files/<file_id>', methods=['GET'])
@token_required
def get_file(file_id):
    for filename in os.listdir(app.config['UPLOAD_FOLDER']):
        if filename.startswith(file_id):
            filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
