import random
from datetime import datetime

def generate_unique_book_id(existing_ids):
    while True:
        new_id = f""BOOK-{random.randint(1000, 9999)}""
        if new_id not in existing_ids:
            return new_id

def generate_random_publication_date():
    start_year = 1950
    end_year = datetime.now().year
    year = random.randint(start_year, end_year)
    month = random.randint(1, 12)
    day = random.randint(1, 28)  # Simplified to avoid invalid dates
    return datetime(year, month, day).strftime('%Y-%m-%d')

def generate_random_genre():
    genres = [""Fiction"", ""Non-Fiction"", ""Science Fiction"", ""Mystery"", ""Fantasy"", 
              ""Biography"", ""History"", ""Self-help""]
    return random.choice(genres)

def create_library_item(existing_ids):
    try:
        book_id = generate_unique_book_id(existing_ids)
        publication_date = generate_random_publication_date()
        genre = generate_random_genre()
        library_item = {
            ""book_id"": book_id,
            ""publication_date"": publication_date,
            ""genre"": genre
        }
        return library_item, existing_ids + [book_id]
    except Exception as e:
        print(f""Error creating library item: {e}"")
        return None, existing_ids

def generate_library_items(num_items):
    library_items = []
    existing_ids = []

    for _ in range(num_items):
        item, existing_ids = create_library_item(existing_ids)
        if item:
            library_items.append(item)

    return library_items

