lib = cdll.LoadLibrary('./image_processing.so')

class ImageConfig(Structure):
    _fields_ = [
        (""width"", c_int),
        (""height"", c_int),
        (""quality"", c_int),
        (""format"", c_char_p),
    ]

def parse_config(config_path):
    with open(config_path, 'r') as file:
        return json.load(file)

def resize_images(configs):
    for config in configs['image_configs']:
        image_list = config['images']
        dimensions = ImageConfig(
            width=config['width'],
            height=config['height'],
            quality=config['quality'],
            format=config['format'].encode('utf-8')
        )

        for image_path in image_list:
            resized_image_path = f""{os.path.splitext(image_path)[0]}_resized.{config['format']}""
