    metadata_str = json.dumps(config['metadata'])
    encrypted_metadata = encrypt_metadata(metadata_str, key)
    print(f""Encrypted Metadata: {encrypted_metadata}"")

    resize_images(config)

if __name__ == ""__main__"":
