- Implement caching to avoid redundant parsing of valid files during subsequent function calls.",['CWE-121'],,"['```python
import os
import json
from jsonschema import validate, ValidationError

# Cache for storing parsed and validated JSON objects
cache = {}

def load_and_validate_configs(directory_path, schema):
    if not os.path.exists(directory_path) or not os.path.isdir(directory_path):
        raise FileNotFoundError(""The specified directory does not exist."")

    files = [f for f in os.listdir(directory_path) if f.endswith('.json')]
    result = {}
    error_messages = []

    if not files:
        return {""error"": ""No JSON files found in the directory.""}

    for file_name in files:
        file_path = os.path.join(directory_path, file_name)

        # Check cache first
        if file_name in cache:
            result[file_name] = cache[file_name]
            continue

        try:
            with open(file_path, 'r') as file:
                data = json.load(file)

            validate(instance=data, schema=schema)  # Validate against the provided schema

            total_keys = len(data.keys())
            result[file_name] = total_keys
            cache[file_name] = total_keys

        except (json.JSONDecodeError, ValidationError) as e:
            error_messages.append(f""File '{file_name}' failed validation: {str(e)}"")

    if error_messages:
        return {""errors"": error_messages}

    return result

# Example usage with a schema
schema_example = {
    ""type"": ""object"",
    ""properties"": {
        ""name"": {""type"": ""string""},
        ""version"": {""type"": ""number""}
    },
    ""required"": [""name"", ""version""]
}

# Call the function with the directory path and schema
directory_path = ""/path/to/configs""
print(load_and_validate_configs(directory_path, schema_example))
