import os
import pickle

class AppState:
    def __init__(self):
        self.sequence_number = 0
        self.states = []

    def load_and_sort_state(self, filename):
        try:
            with open(filename, 'rb') as file:
                # Use pickle for efficient loading and deserialization
                current_state = pickle.load(file)
                # Increment sequence number after loading state
                self.sequence_number += 1

            # Function to extract sequence number from last line of a log file
            def extract_sequence_from_last_line(file_path):
                try:
                    with open(file_path, 'r') as f:
                        lines = f.readlines()
                        if lines:
                            last_line = lines[-1]
                            # Assuming sequence number is in the format: ""Sequence: 12345""
                            seq_num_str = last_line.split("": "")[1]
                            return int(seq_num_str)
                        else:
                            return None
                except Exception as e:
                    print(f""Error occurred while extracting sequence: {e}"")
                    return None

            # Read existing sequence number from a log file (assuming it's also saved in a text file)
            existing_seq_num = extract_sequence_from_last_line(filename)

            if existing_seq_num is not None:
                self.sequence_number += existing_seq_num

            # Save updated state back to file using pickle for efficient serialization
            with open(filename, 'wb') as file:
                pickle.dump(self, file)

        except FileNotFoundError:
            print(""File not found. Creating new state object."")
        except Exception as e:
            print(f""An error occurred while loading or saving state: {e}"")

    def process_operations(self, operation_data):
        self.states.append(operation_data)
        return self.sequence_number

    def display_operations(self):
        if not self.states:
            print(""No operations recorded."")
        else:
            print(""Operations:"")
            for index, operation in enumerate(self.states):
                print(f""{index + 1}. {operation}"")

# Example usage
app_instance = AppState()
resulting_sequence_number = app_instance.load_and_sort_state(""app_data.pickle"")
print(f""The resulting sequence number after loading is: {resulting_sequence_number}"")

app_instance.process_operations({""operation"": ""add"", ""value"": 5})
app_instance.process_operations({""operation"": ""subtract"", ""value"": 3})

resulting_sequence_number += 2

print(f""The resulting sequence number after processing operations is: {resulting_sequence_number}"")

app_instance.display_operations()
