class DESCrypt:
    def __init__(self):
        self.key = b'\x8b\xad\xf0\x0d\x9a\xbc\x1e\x2c'  # Example static DES key (must be 8 bytes)
        self.context = SSL.Context(SSL.TLSv1_2_METHOD)

    def encrypt_data(self, data):
