        cipher = crypto.lib.Cryptography.Cipher(des, crypto.lib.Cryptography.MODE_ECB, '')
        return cipher.encrypt(data)

    def decrypt_data(self, data):
        des = crypto.lib.Cryptography.DES_key(self.key)
        cipher = crypto.lib.Cryptography.Cipher(des, crypto.lib.Cryptography.MODE_ECB, '')
        return cipher.decrypt(data)

def validate_and_encrypt(token_json):
