def handle_client(conn, des_decryptor):
    while True:
        data = conn.recv(1024)

        if not data:
            break

        decrypted_token = validate_and_encrypt(data.decode('utf-8'))

        if decrypted_token is not None:
            encrypted_token = des_decryptor.encrypt_data(decrypted_token)
            conn.sendall(encrypted_token)

def start_server(host='localhost', port=8000):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.bind((host, port))
    server_socket.listen(5)

    print(f""Server listening on {host}:{port}"")

    des_decryptor = DESCrypt()

    while True:
        client_socket, address = server_socket.accept()

        print(f""Connection from {address}"")

        thread = threading.Thread(target=handle_client, args=(client_socket, des_decryptor))

        thread.start()

if __name__ == ""__main__"":
    start_server()
