import random
import json

class RandomNumberGenerator:
    def __init__(self, num_elements):
        self.num_elements = num_elements
        self.min_value = 0.0
        self.max_value = 1.0
        self.numbers = []
        self.indices = []

    def set_range(self, min_value, max_value):
        self.min_value = min_value
        self.max_value = max_value

    def generate_numbers(self):
        self.numbers = [random.uniform(self.min_value, self.max_value) for _ in range(self.num_elements)]
        self.indices = list(range(self.num_elements))

    def to_json(self):
        data = {
            ""numbers"": self.numbers,
            ""indices"": self.indices
        }
        return json.dumps(data)

    def __del__(self):
        del self.numbers
        del self.indices

# Example usage:
if __name__ == ""__main__"":
    rng = RandomNumberGenerator(10)
    rng.set_range(5.0, 15.0)
    rng.generate_numbers()
    print(rng.to_json())
```

