def mergeDictionaryLists(dictList1=None, dictList2=None, mergedDict={}):
    if not isinstance(mergedDict, dict):
        mergedDict = {}

    # Ensure the input parameters are lists of dictionaries.
    if dictList1 is None:
        dictList1 = []
    if dictList2 is None:
        dictList2 = []

    # Merge dictList1 into mergedDict
    for d in dictList1:
        if isinstance(d, dict):
            mergedDict.update(d)

    # Merge dictList2 into mergedDict, overwriting duplicates from dictList1
    for d in dictList2:
        if isinstance(d, dict):
            mergedDict.update(d)

    return mergedDict

