import gzip
import sys

def decompress_gzip_file(file_path):
    try:
        with gzip.open(file_path, 'rt', encoding='utf-8') as f:
            content = f.read()
            print(content)
    except Exception as e:
        print(f""Error decompressing file {file_path}: {e}"")

if __name__ == ""__main__"":
    if len(sys.argv) != 2:
        print(""Usage: python3 decompress_gzip.py <compressed_file_path>"")
    else:
        decompress_gzip_file(sys.argv[1])
```

