import ctypes
from typing import List, Dict
import requests

# Load the shared library (compiled C++ code)
lib = ctypes.CDLL('./crypto_lib.so')

def forward_list_insertion(forward_list: List[Dict], search_str: str, insert_str: str) -> List[Dict]:
    found = False
    for i, item in enumerate(forward_list):
        if search_str in item.values():
            forward_list.insert(i + 1, {""text"": lib.encrypt_string(insert_str.encode('utf-8'))})
            found = True
            break

    if not found:
        forward_list.append({""text"": lib.encrypt_string(insert_str.encode('utf-8'))})

    return forward_list

def send_to_api(forward_list: List[Dict], api_url: str) -> Dict:
