    def __init__(self):
        self.memory = []

    def push(self, value: int) -> None:
        self.memory.append(value)
        print(f""Allocated {value} in memory."")

    def pop(self) -> int:
        if self.memory:
            value = self.memory.pop()
            print(f""Deallocated {value} from memory."")
            return value
        raise IndexError(""Pop from empty list"")

