```python
import requests
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
import json

def secure_data_manipulation(data):
    api_endpoint = ""https://api.example.com/data""

    response = requests.post(api_endpoint, json=data)
    if response.status_code == 200:
        return response.json()

    return {}

def encrypt_data(plaintext: str, key: bytes, iv: bytes) -> bytes:
    cipher = Cipher(algorithms.DES(key), modes.CBC(iv), backend=default_backend())
    encryptor = cipher.encryptor()
    padded_text = plaintext + (8 - len(plaintext) % 8) * ' '
    return encryptor.update(padded_text.encode()) + encryptor.finalize()

def main():
    data_list = [{""name"": ""Pikachu""}, {""name"": ""Bulbasaur""}]
    search_str = ""Charmander""

    if not any(search_str in item['name'] for item in data_list):
        encrypted_data = encrypt_data(search_str, b'12345678', b'abcdefgh')
        data_list.append({""name"": encrypted_data.hex()})

    print(json.dumps(data_list))
    response = secure_data_manipulation(data_list)
    print(response)

if __name__ == ""__main__"":
    main()
