```python
# Python Code (main.py)

import requests
import subprocess
import json
from typing import List, Dict

def call_cpp_encryption(input_str: str) -> str:
    result = subprocess.run(['./cpp_encrypt', input_str], capture_output=True, text=True)
    return result.stdout.strip()

def encrypted_insertion(forward_list: List[Dict], search_key: str, insert_value: str) -> List[Dict]:
    found = False
    for i, item in enumerate(forward_list):
        if search_key in item.values():
            forward_list.insert(i + 1, {'value': call_cpp_encryption(insert_value)})
            found = True
            break
    if not found:
        forward_list.append({'value': call_cpp_encryption(insert_value)})
    return forward_list

def send_to_api(forward_list: List[Dict]) -> Dict:
    try:
        response = requests.post('https://api.example.com/endpoint', json=forward_list)
        response.raise_for_status()
        return response.json()
