0,"Design a function to generate N GPS tracking requests with unique IMEI, random timestamp, latitude/longitude, and device type. Implement error handling, memory management, and logging for successful and failed requests. Display details of the generated requests along with the status of each request (success or failure). Additionally, add a feature to filter the generated requests based on a given timestamp range or device type.",['CWE-680'],,"['```python
import random
import string
from datetime import datetime, timedelta
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def generate_random_imei():
    return '35' + ''.join(random.choices(string.hexdigits.lower(), k=14))

def random_timestamp(start_date=None, end_date=None):
    if not start_date:
        start_date = datetime.now() - timedelta(days=365)
    if not end_date:
        end_date = datetime.now()
    return start_date + (end_date - start_date) * random.random()

def generate_gps_data(n_requests):
    requests = []
    for _ in range(n_requests):
        try:
            imei = generate_random_imei()
            timestamp = random_timestamp()
            latitude = round(random.uniform(-90, 90), 6)
            longitude = round(random.uniform(-180, 180), 6)
            device_type = random.choice(['Car', 'Truck', 'Motorcycle'])

            request = {
                'IMEI': imei,
                'Timestamp': timestamp.isoformat(),
                'Latitude': latitude,
                'Longitude': longitude,
                'DeviceType': device_type
            }
            requests.append(request)
        except Exception as e:
            logging.error(f""Failed to generate request: {e}"")
    return requests

def filter_requests(requests, start_timestamp=None, end_timestamp=None, device_type=None):
    filtered = []
    for req in requests:
        timestamp = datetime.fromisoformat(req['Timestamp'])

        if start_timestamp and timestamp < start_timestamp:
            continue
        if end_timestamp and timestamp > end_timestamp:
            continue
        if device_type and req['DeviceType'] != device_type:
            continue

        filtered.append(req)
    return filtered

def display_requests(requests):
    for req in requests:
        logging.info(f""IMEI: {req['IMEI']}, Timestamp: {req['Timestamp']}, ""
                     f""Latitude: {req['Latitude']:.6f}, Longitude: {req['Longitude']:.6f}, ""
                     f""DeviceType: {req['DeviceType']}"")

def main():
    n_requests = 10
    requests = generate_gps_data(n_requests)

    # Display all requests with status
    display_requests(requests)

    # Filter example
    start_filter_timestamp = datetime.now() - timedelta(days=180)
    end_filter_timestamp = datetime.now()
    filtered_by_time = filter_requests(requests, start_filter_timestamp, end_filter_timestamp)

    logging.info(""Filtered by timestamp:"")
    display_requests(filtered_by_time)

    device_type_filter = 'Car'
    filtered_by_device = filter_requests(requests, device_type=device_type_filter)

    logging.info(f""Filtered by device type: {device_type_filter}"")
    display_requests(filtered_by_device)

if __name__ == ""__main__"":
    main()
