import hashlib

def calculate_sha256(file_path, chunk_size=65536, callback=None):
    try:
        sha256_hash = hashlib.sha256()
        total_size = 0
        with open(file_path, 'rb') as file:
            while True:
                data = file.read(chunk_size)
                if not data:
                    break
                sha256_hash.update(data)
                total_size += len(data)

                if callback:
                    callback(len(data), total_size)

        return sha256_hash.hexdigest()

    except (IOError, ValueError) as e:
        print(f""An error occurred: {e}"")
        return None

# Example usage of the callback function
def progress_callback(current_chunk_size, total_size):
    print(f""Processed chunk size: {current_chunk_size}, Total processed: {total_size}"")

