import time
import hashlib
import random
from typing import List, Dict

def generate_token() -> str:
    # Use current timestamp combined with a random number to create a unique seed for each token
    raw_seed = f""{int(time.time())}-{random.randint(100000, 999999)}""
    # Hash the seed using SHA-256 for security
    return hashlib.sha256(raw_seed.encode()).hexdigest()

def create_auth_tokens(size: int, session_duration: str) -> List[Dict[str, any]]:
    try:
        tokens = []

        for _ in range(size):
            token = generate_token()
            expiration_time = calculate_expiration(session_duration)
            token_entry = {
                'token': token,
                'expiration_time': expiration_time,
                'session_status': 'active',
                'user_role': random.choice(['admin', 'editor', 'viewer'])
            }

            if authenticate_token(token_entry):
                tokens.append(token_entry)

        return tokens

    except MemoryError:
        print(""Memory allocation failed."")
        return []

def calculate_expiration(session_duration: str) -> int:
    current_time = time.time()

    if session_duration.endswith('h'):
        hours = int(session_duration[:-1])
        return current_time + (hours * 3600)
    elif session_duration.endswith('d'):
        days = int(session_duration[:-1])
