import gc

def mergeDictionaryListsAdvanced(dictList1, dictList2, uniqueKeyList=None, mergedDict=None):
    """"""
    Merges two lists of dictionaries into a single dictionary.

    Parameters:
    - dictList1: List[Dict]. First list of dictionaries to be merged. None is allowed and treated as an empty list.
    - dictList2: List[Dict]. Second list of dictionaries with precedence over the first in case of key conflicts.
    - uniqueKeyList: Optional[List[str]]. Keys that should remain unique across both lists based on specific criteria.
                      The last occurrence value is used if present.
    - mergedDict: Optional[Dict]. Dictionary to be populated with merged values. If None, a new dictionary is created.

    Returns:
    Dict: A merged dictionary containing key-value pairs from dictList1 and dictList2.

    Raises:
    ValueError: If any of the provided parameters are not lists or dictionaries as expected.
    """"""

    # Validate input types
    if not isinstance(dictList1, list) or (dictList1 is not None and not all(isinstance(d, dict) for d in dictList1)):
        raise ValueError(""dictList1 should be a list of dictionaries."")

    if not isinstance(dictList2, list) or (dictList2 is not None and not all(isinstance(d, dict) for d in dictList2)):
        raise ValueError(""dictList2 should be a list of dictionaries."")

    if uniqueKeyList is not None and not isinstance(uniqueKeyList, list):
        raise ValueError(""uniqueKeyList should be a list of strings."")

    if mergedDict is not None and not isinstance(mergedDict, dict):
        raise ValueError(""mergedDict should be a dictionary."")

    # Handle null inputs
    dictList1 = [] if dictList1 is None else dictList1
    dictList2 = [] if dictList2 is None else dictList2

    # Initialize mergedDict if not provided
    if mergedDict is None:
        mergedDict = {}

    # Merge dictionaries, prioritizing dictList2
    for d in reversed(dictList1):
        mergedDict.update(d)

    for d in dictList2:
        mergedDict.update(d)

    # Handle unique keys based on the criteria in uniqueKeyList
    if uniqueKeyList:
        temp_dict = {}
        for key in uniqueKeyList:
            values = [d[key] for d in reversed(dictList1 + dictList2) if key in d]
            if values:
                mergedDict[key] = values[-1]

    # Clear references to allow garbage collection
    del dictList1, dictList2

    # Force garbage collection
    gc.collect()

    return mergedDict

