import os
import hashlib
import time
from datetime import datetime, timedelta

class Token:
    def __init__(self, value, expiration, session_status, user_role):
        self.value = value
        self.expiration = expiration
        self.session_status = session_status
        self.user_role = user_role

    def is_valid(self):
        return datetime.now() < self.expiration

def generate_token_value():
    random_bytes = os.urandom(16)
    token_hash = hashlib.sha256(random_bytes).hexdigest()
    return token_hash[:32]  # Use the first 32 characters for a short token representation

def create_tokens(size, duration, user_role):
    tokens = []

    if size <= 0:
        raise ValueError(""Size parameter must be positive."")

    try:
        for _ in range(size):
            value = generate_token_value()
            expiration_time = datetime.now() + timedelta(hours=duration)
            token = Token(value, expiration_time, ""active"", user_role)

            # Authenticating before adding
            if authenticate_token(token):
                tokens.append(token)

    except MemoryError:
        print(""Memory allocation failed during token generation."")

    return tokens

def authenticate_token(token):
    # Simple mock authentication logic: just ensure the session status is ""active""
    return token.session_status == ""active""

# Example Usage
try:
    user_tokens = create_tokens(10, 1, 'admin')
    for token in user_tokens:
        print(f""Token: {token.value}, Expires at: {token.expiration}, Role: {token.user_role}"")
except ValueError as e:
    print(e)
