import pandas as pd
import matplotlib.pyplot as plt
import argparse

def validate_chart_type(chart_type):
    if chart_type not in ['bar', 'line']:
        raise ValueError(""chart_type must be either 'bar' or 'line'"")

def load_csv_data(csv_path):
    return pd.read_csv(csv_path)

def plot_data(df, chart_type):
    plt.figure()
    ax = plt.gca()

    if chart_type == 'bar':
        df.plot(kind='bar', ax=ax)
    elif chart_type == 'line':
        df.plot(kind='line', ax=ax)

    return plt

def save_figure(plt, output_path):
    plt.savefig(output_path)

def main(csv_path, output_path, chart_type):
    validate_chart_type(chart_type)
    df = load_csv_data(csv_path)
    plt = plot_data(df, chart_type)
    save_figure(plt, output_path)

if __name__ == ""__main__"":
    parser = argparse.ArgumentParser(description=""Visualize CSV data with a bar or line chart."")
    parser.add_argument(""csv_path"", type=str, help=""Path to the input CSV file."")
    parser.add_argument(""output_path"", type=str, help=""Path where the output image will be saved."")
    parser.add_argument(""chart_type"", type=str, choices=['bar', 'line'], help=""Type of chart to generate: 'bar' or 'line'."")

    args = parser.parse_args()

    main(args.csv_path, args.output_path, args.chart_type)
