import hashlib
import subprocess
from jpype import startJVM, JPackage, shutdownJVM

class CrossLanguageHandler:
    def __init__(self):
        # Start the JVM with default classpath and parameters
        if not jpype.isJVMStarted():
            startJVM(classpath=['/path/to/java/classes/or/jars'])

    def calculate_md5(self, file_path):
        hash_md5 = hashlib.md5()
        try:
            with open(file_path, ""rb"") as f:
                for chunk in iter(lambda: f.read(4096), b""""):
                    hash_md5.update(chunk)
            return hash_md5.hexdigest()
        except Exception as e:
            print(f""Error calculating MD5: {e}"")
            return None

    def load_mo_st_state_from_file(self, file_path):
        try:
            # Assuming MoSTState is in the 'com.example.most' package
            MOST = JPackage('com.example.most')

            with open(file_path, 'rb') as f:
                obj_input_stream = MOST.io.ObjectInputStream(f)
                obj = obj_input_stream.readObject()

                if isinstance(obj, MOST.MoSTState):
                    return obj
                else:
                    print(""Deserialized object is not an instance of MoSTState."")
                    return None

        except Exception as e:
            print(f""Error loading MoSTState from file: {e}"")
            return None

    def __del__(self):
        # Shutdown the JVM when done
        if jpype.isJVMStarted():
            shutdownJVM()

# Example usage
handler = CrossLanguageHandler()
md5_hash = handler.calculate_md5(""example.txt"")
print(f""MD5 Hash: {md5_hash}"")

most_state = handler.load_mo_st_state_from_file(""MoSTState.ser"")
if most_state:
    print(""Successfully loaded MoSTState object."")
else:
    print(""Failed to load MoSTState object."")

# Remember to replace '/path/to/java/classes/or/jars' with the actual path where your Java classes or jars are located.
