import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

# Define the API endpoints for multiple feeds
FEED_URLS = [
    'https://api.example.com/feed1',
    'https://api.example.com/feed2',
    'https://api.example.com/feed3',
]

def fetch_data(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        return response.json()  # Assuming the API returns JSON
    except (requests.exceptions.RequestException, ValueError) as e:
        print(f""Error fetching {url}: {e}"")
        return None

def process_data(data):
    # Placeholder for data processing logic
    if data is not None:
        # Process data here
        return f""Processed: {data}""
    return ""No valid data to process""

def main():
    processed_results = []

    with ThreadPoolExecutor(max_workers=5) as executor:
        future_to_url = {executor.submit(fetch_data, url): url for url in FEED_URLS}

        for future in as_completed(future_to_url):
            url = future_to_url[future]
            data = future.result()
            processed_result = process_data(data)
            if processed_result != ""No valid data to process"":
                processed_results.append(processed_result)

    # Output the processed results
    for result in processed_results:
        print(result)

if __name__ == ""__main__"":
    main()
