from Crypto.Util.Padding import unpad, pad
from enum import Enum

class PaddingScheme(Enum):
    PKCS7 = 'pkcs7'
    ISO10126_PKCS5 = 'iso10126_pkcs5'
    ANSI_X923 = 'ansi_x923'

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rnti, crc_flag_status):
        self.rnti = rnti
        self.crc_flag_status = crc_flag_status

class CryptoLibrary:

    @staticmethod
    def decrypt(ciphertext: bytes, key: bytes, iv: bytes, padding_scheme: PaddingScheme) -> bytes:
        if len(key) not in [16, 24, 32]:
            raise ValueError(""Invalid key size"")

        try:
            cipher = AES.new(key, AES.MODE_CBC, iv)
            padded_data = unpad(cipher.decrypt(ciphertext), AES.block_size,
                                style=padding_scheme.value)
        except (ValueError, KeyError) as e:
            raise ValueError(f""Decryption failed: {e}"")

        return padded_data

    @staticmethod
    def generate_crc_indication_tags(num_tags: int):
        tags = []
        for _ in range(num_tags):
            rnti = random.randint(0x00FF0001, 0x00FFFFFF)
            crc_flag_status = bool(random.getrandbits(1))
            tags.append(NFAPI_CRC_INDICATION_PDU_T(rnti, crc_flag_status))

        return tags

    @staticmethod
    def generate_random_floats(num_floats: int, lower_bound: float, upper_bound: float):
        floats = [(random.uniform(lower_bound, upper_bound), idx) for idx in range(num_floats)]
        sorted_floats = sorted(floats)
        total_sum = sum(f[0] for f in sorted_floats)
        average_value = total_sum / num_floats

        return {
            'sorted_floats': [f[0] for f in sorted_floats],
            'indices': [f[1] for f in sorted_floats],
            'sum': total_sum,
            'average': average_value
        }

    @staticmethod
    def process_encryption_settings(key: bytes, iv: bytes, padding_scheme: PaddingScheme):
        # This function would handle CLI inputs or configurations.
        return key, iv, padding_scheme

