import random
import string
from datetime import datetime, timedelta

class NAT:
    def __init__(self, access_token, user_id, token_expiration_date):
        self.ACCESS_TOKEN = access_token
        self.USER_ID = user_id
        self.TOKEN_EXPIRATION_DATE = token_expiration_date

def generate_random_string(length=40):
    return ''.join(random.choices(string.ascii_letters + string.digits, k=length))

def generate_random_user_id():
    return random.randint(1000, 9999)

def generate_token_expiration_date(days_from_now=30):
    return datetime.now() + timedelta(days=days_from_now)

def create_nat_objects(n):
    nat_list = []
    for _ in range(n):
        access_token = generate_random_string()
        user_id = generate_random_user_id()
        token_expiration_date = generate_token_expiration_date()
        nat_object = NAT(access_token, user_id, token_expiration_date)
        nat_list.append(nat_object)
    return nat_list
