import random
import json

class JSONMacReceiver:
    def __init__(self):
        self.registry = {}
        self.generated_flows = set()
        self.cache = {}

    def add_factory(self, id, factory_function):
        self.registry[id] = factory_function

    def generate_random_values(self, flow_id_range=(1000, 9999), src_addr_range=('0.0.0.1', '255.255.255.254'), dst_addr_range=('0.0.0.1', '255.255.255.254'), tc_range=(1, 7)):
        while True:
            flow_id = random.randint(*flow_id_range)
            if flow_id not in self.generated_flows:
                break
        src_address = '.'.join(map(str, [random.randint(*map(int, addr.split('.'))) for addr in src_addr_range]))
        dst_address = '.'.join(map(str, [random.randint(*map(int, addr.split('.'))) for addr in dst_addr_range]))

        self.generated_flows.add(flow_id)

        return {
            'flow_identifier': flow_id,
            'source_address': src_address,
            'destination_address': dst_address,
            'traffic_class': random.randint(*tc_range)
        }

    def create_entity(self, id):
        if id not in self.registry:
            raise ValueError(""Factory function not registered with the given ID."")

        entity = self.cache.get(id)
        if not entity:
            entity = self.registry[id](**self.generate_random_values())
            self.cache[id] = entity

        return entity

    def to_json_string(self, entity):
        # Custom serialization: Encode specific attributes differently if needed
        def custom_encoder(obj):
            if isinstance(obj, str) and obj.startswith(""SampleEntity""):
                return {""type"": ""SampleEntity"", ""id"": int(obj.split(' ')[1])}
            raise TypeError(f""Object of type {obj.__class__.__name__} is not JSON serializable"")

        return json.dumps(entity, default=custom_encoder)

def sample_factory(id):
    if id == 1:
        return lambda **kwargs: f""SampleEntity{kwargs['flow_identifier']}""
    else:
        raise ValueError(""Invalid ID for sample factory."")

mac_receiver = JSONMacReceiver()
mac_receiver.add_factory(1, sample_factory)

entities = [mac_receiver.create_entity(1) for _ in range(3)]
json_strings = [mac_receiver.to_json_string(entity) for entity in entities]

# Output the json strings
for js in json_strings:
    print(js)
```']",0,[0],[],True,0,0,0,

