# File: nfa_api.py

import random
from typing import List, Dict

def generate_crc_flag():
    return random.randint(1000, 9999)

class NFAPICRCIndicationPDU:
    def __init__(self, rx_ue_information_tag: str, rnti: int):
        self.rx_ue_information_tag = rx_ue_information_tag
        self.rnti = rnti
        self.crc_indication_rel8_tag = {
            ""CRCFLAG"": generate_crc_flag()
        }

    def custom_display(self) -> Dict:
        return {
            ""RX_UE_INFORMATION_TAG"": self.rx_ue_information_tag,
            ""RNTI"": self.rnti,
            ""CRC_INDICATION_REL8_TAG"": self.crc_indication_rel8_tag
        }

def create_pokemon_weakness_array(pokemons: List[Dict]) -> List[NFAPICRCIndicationPDU]:
    return [NFAPICRCIndicationPDU(p['rx_ue_information_tag'], p['rnti']) for p in pokemons]

# Usage Example:
pokemons = [
    {""rx_ue_information_tag"": ""Tag1"", ""rnti"": 12345},
    {""rx_ue_information_tag"": ""Tag2"", ""rnti"": 67890}
]

nfa_structs = create_pokemon_weakness_array(pokemons)
for nfa in nfa_structs:
    print(nfa.custom_display())
