def send_to_api(job_applications):
    url = ""http://api.example.com/jobapplications""
    headers = {'Content-Type': 'application/json'}
    response = requests.post(url, data=json.dumps([app.display() for app in job_applications]), headers=headers)
    return response.json()

# Example usage
