import sys

def display_usage():
    usage_message = (
        ""Usage:\n""
        ""--manpage           : Display this help message.\n""
        ""-cs <input_file>    : Count and print the number of lines in the input file.\n""
        ""-o <output_file>    : Specify an output file for the line count results.\n\n""
        ""Example:\n""
        ""  python your_program.py --manpage\n""
        ""  python your_program.py -cs input.txt\n""
        ""  python your_program.py -cs input.txt -o output.txt""
    )
    print(usage_message)

def count_lines(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            return len(lines)
    except FileNotFoundError:
        sys.exit(f""Error: File '{file_path}' not found."")
    except Exception as e:
        sys.exit(f""An error occurred: {e}"")

def main():
    if len(sys.argv) == 1:
        display_usage()
        return

    input_file = sys.argv[0]
    output_file = None
    line_count = 0

    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]

        if arg == ""--manpage"":
            display_usage()

        elif arg == ""-cs"" and (i + 1) < len(sys.argv):
            input_file = sys.argv[i + 1]
            line_count = count_lines(input_file)
            i += 1

        elif arg.startswith(""-o="") and len(arg.split(""="")) == 2:
            output_file = arg.split(""="", 1)[1]

        elif arg == ""-o"" and (i + 1) < len(sys.argv):
            output_file = sys.argv[i + 1]
            i += 1

        else:
            print(f""Unknown option: {arg}"")
            display_usage()
            return

        i += 1

    if line_count > 0:
        result_message = f""The file '{input_file}' has {line_count} lines.""

        if output_file:
            try:
                with open(output_file, 'w') as outfile:
                    outfile.write(result_message)
                print(f""Output written to '{output_file}'."")
            except Exception as e:
                sys.exit(f""An error occurred writing to '{output_file}': {e}"")
        else:
            print(result_message)

if __name__ == ""__main__"":
    main()
