import string

def modify_text_array(n, text, capitalize):
    if not isinstance(n, int) or n <= 0:
        raise ValueError(""The first parameter must be a positive integer."")
    if not isinstance(text, str):
        raise ValueError(""The second parameter must be a string."")
    if not isinstance(capitalize, bool):
        raise ValueError(""The third parameter must be a boolean."")

    result = []

    for i in range(n):
        if i % 2 == 0:
            modified_text = text.upper() if capitalize else text
        else:
            modified_text = ''.join(
                char for char in text if char not in string.punctuation
            )

        result.append(modified_text)

    return result

# Example usage:
# print(modify_text_array(5, ""Hello, World!"", True))
