```python
import ctypes

class CustomRandomGenerator:
    def generate(self):
        # Implement custom random logic here
        import random
        return random.randint(1, 1000000)

class NFAPI_CRC_INDICATION_PDU_T(ctypes.Structure):
    _fields_ = [(""crcFlags"", ctypes.c_uint),
                (""eventData"", ctypes.c_char * 100)]

class CrossLanguageHandler:
    def __init__(self, lib_path):
        self.lib = ctypes.CDLL(lib_path)
        self.random_gen = CustomRandomGenerator()

    def create_pdu(self, event_name):
        # Create a PDU structure and set its fields
        pdu = NFAPI_CRC_INDICATION_PDU_T()
        pdu.crcFlags = self.random_gen.generate()
        pdu.eventData = bytes(event_name.encode('utf-8'), 'utf-8')

        return pdu

    def process_pdu(self, pdu):
        # Simulate processing of PDU in Python
        print(f""Processing event: {pdu.eventData.decode('utf-8')} with CRC Flags: {pdu.crcFlags}"")

# Example usage
if __name__ == ""__main__"":
    handler = CrossLanguageHandler('./path_to_your_c_library.so')

    pdu = handler.create_pdu(""LoginEvent"")
    handler.process_pdu(pdu)
```

