def generate_rx_ue_information_tag():
    return random.getrandbits(32)

# Placeholder for RNTI assignment
def generate_rnti():
    return random.getrandbits(16)

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rx_ue_info_tag, rnti, crc_flag):
        self.rx_ue_information_tag = rx_ue_info_tag
        self.rnti = rnti
        self.crc_indication_rel8_tag = crc_flag

def generate_security_cryptography_pdu(n, key_length, entity_size):
    # Validate inputs
    if n <= 0 or key_length <= 1024 or entity_size <= 0:
        raise ValueError(""Invalid input parameters"")

    # Initialize the security_cryptography_pdu array
    security_cryptography_pdu = []

    for _ in range(n):
        try:
            # RSA Key Generation
            rsa_key = RSA.generate(key_length)
            public_key_bytes = rsa_key.publickey().exportKey()
            private_key_bytes = rsa_key.exportKey()

            public_key_bits = int.from_bytes(public_key_bytes, byteorder='big')
            private_key_bits = int.from_bytes(private_key_bytes, byteorder='big')

            # Extract prime numbers used in key generation
            p, q = rsa_key.p, rsa_key.q

            # Generate PDU entity
            rx_ue_info_tag = generate_rx_ue_information_tag()
            rnti = generate_rnti()
            crc_flag = random.choice([0x1, 0x2])  # Example CRCFLAG values

            pdu_entity = NFAPI_CRC_INDICATION_PDU_T(rx_ue_info_tag, rnti, crc_flag)

            # Append to security_cryptography_pdu
            security_cryptography_pdu.append({
                'rsa_keys': {
                    'public_key_bits': public_key_bits,
                    'private_key_bits': private_key_bits,
                    'prime_numbers': (p, q)
                },
                'pdu_entity': pdu_entity.__dict__
            })

        except Exception as e:
            raise MemoryError(""Memory allocation failed"") from e

    return security_cryptography_pdu
