def create_network_node_configurations(count, memory_size, processing_power):
    if count < 0 or memory_size < 0 or processing_power < 0:
        raise ValueError(""All input parameters must be non-negative."")

    # Assume total system bandwidth and available system memory for simulation purposes.
    TOTAL_SYSTEM_BANDWIDTH = 10000  # Example value in Mbps
    AVAILABLE_MEMORY = 1024 * 1024 * 1024  # 1 GB in bytes

    network_node_configurations = []

    if count * memory_size > AVAILABLE_MEMORY:
        raise MemoryError(""Insufficient available system memory for the requested nodes."")

    try:
        total_processing_power = processing_power * count

        for node_id in range(1, count + 1):
            allocated_bandwidth_percentage = (processing_power / total_processing_power) * 100
            configuration = {
                ""Node ID"": f""Node_{node_id}"",
                ""Memory Allocation"": memory_size,
                ""Processing Power (MHz)"": processing_power,
                ""Bandwidth (%)"": allocated_bandwidth_percentage
            }
            network_node_configurations.append(configuration)

    except Exception as e:
        raise RuntimeError(f""Failed to allocate resources: {e}"")

    return network_node_configurations

