def find_largest_int(arr):
    max_val = float('-inf')
    for num in arr:
        if isinstance(num, int) and num > max_val:
            max_val = num
    return max_val if max_val != float('-inf') else None

def load_and_validate_jsons(dir_path):
    valid_files_cache = defaultdict(bool)

    for file_name in os.listdir(dir_path):
        if file_name.endswith('.json'):
            json_file_path = os.path.join(dir_path, file_name)
            with open(json_file_path) as json_file:
                try:
                    data = json.load(json_file)
                    if not valid_files_cache[file_name]:
                        if validate_json(data):
                            keys_count = count_keys(data)
                            print(f""File '{file_name}' has {keys_count} keys."")
