                            else:
                                print(f""No integers found in '{file_name}'."")
                        else:
                            print(f""Validation failed for '{file_name}'"")
                except Exception as e:
                    print(f""Error parsing '{file_name}': {e}"")
                finally:
                    valid_files_cache[file_name] = True

