import subprocess
import signal

class TimeoutException(Exception):
    pass

def handle_timeout(signum, frame):
    raise TimeoutException(""Script execution exceeded the time limit"")

def execute_script(script_path, input_params=None, timeout=None):
    try:
        process = subprocess.Popen(
            [script_path] + (input_params if input_params else []),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )

        signal.signal(signal.SIGALRM, handle_timeout)
        if timeout is not None:
            signal.alarm(timeout)

        stdout, stderr = process.communicate()

        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, script_path, output=stdout, stderr=stderr)

        return stdout.decode('utf-8').strip()

    except TimeoutException as e:
        process.kill()
        process.wait()
        raise e

    except Exception as e:
        if process.poll() is None:  # If the process is still running
            process.kill()
            process.wait()
        raise e

    finally:
        signal.alarm(0)  # Disable the alarm

# Usage examples:

try:
