class StringManipulator:
    def __init__(self):
        self.strings = []
        self.delimiter = """"

    def set_delimiter(self, delimiter):
        self.delimiter = delimiter

    def add_string(self, string):
        self.strings.append(string)

    def concatenate(self):
        return self.delimiter.join(self.strings)

    def reverse_concatenation(self):
        reversed_strings = self.strings[::-1]
        return self.delimiter.join(reversed_strings)

    def __str__(self):
        string_order = "", "".join([f""'{s}'"" for s in self.strings])
        return f""Order of strings: [{string_order}]""

# Example usage:
manipulator = StringManipulator()
manipulator.set_delimiter("", "")
manipulator.add_string(""Hello"")
manipulator.add_string(""World"")
print(manipulator)  # Displays order
concatenated = manipulator.concatenate()
reversed_concatenation = manipulator.reverse_concatenation()

print(concatenated)
print(reversed_concatenation)
